export const COUNTRY_BY_ISO3: Record<string, WorldCountry> = Object.fromEntries(
  ALL_COUNTRIES.map((c) => [c.iso3, c])
);

export const COUNTRY_BY_ISO2: Record<string, WorldCountry> = Object.fromEntries(
  ALL_COUNTRIES.map((c) => [c.iso2, c])
);

export function findCountry(iso?: string | null): WorldCountry | undefined {
  if (!iso) return undefined;
  return COUNTRY_BY_ISO3[iso.toUpperCase()] ?? COUNTRY_BY_ISO2[iso.toUpperCase()];
}
